package com.example.appsaudebackend.Medico.Service;
import com.example.appsaudebackend.Modules.Medico.Dto.Request.AtualizarMedicoRequestDto;import com.example.appsaudebackend.Modules.Medico.Persistencia.*;import com.example.appsaudebackend.Modules.Medico.Service.MedicoPerfilService;import com.example.appsaudebackend.Shared.Exception.*;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.util.Optional;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class MedicoPerfilServiceTest{@Mock MedicoRepository repo;@InjectMocks MedicoPerfilService service;private MedicoModel med(){var m=new MedicoModel();m.setId(2L);m.setNome("Dr A");m.setEmail("a@x.com");m.setTelefone("111");m.setCrm("CRM1");m.setEspecialidade("Cardio");return m;}
@Test void consultaPerfil(){when(repo.findByUsuarioAuthCpf("1")).thenReturn(Optional.of(med()));var r=service.obter("1");assertEquals("CRM1",r.crm());assertEquals("Cardio",r.especialidade());}
@Test void atualizaPerfil(){var m=med();when(repo.findByUsuarioAuthCpf("1")).thenReturn(Optional.of(m));when(repo.findByEmailAndIdNot("b@x.com",2L)).thenReturn(Optional.empty());when(repo.save(m)).thenReturn(m);var r=service.atualizar("1",new AtualizarMedicoRequestDto("Dr B","b@x.com","222"));assertEquals("Dr B",r.nome());assertEquals("222",m.getTelefone());}
@Test void rejeitaEmailDeOutroMedico(){var m=med();when(repo.findByUsuarioAuthCpf("1")).thenReturn(Optional.of(m));when(repo.findByEmailAndIdNot("b@x.com",2L)).thenReturn(Optional.of(new MedicoModel()));assertThrows(ConflitoException.class,()->service.atualizar("1",new AtualizarMedicoRequestDto("Dr B","b@x.com","222")));verify(repo,never()).save(any());}
@Test void erroQuandoPerfilAusente(){when(repo.findByUsuarioAuthCpf("1")).thenReturn(Optional.empty());assertThrows(RecursoNaoEncontradoException.class,()->service.obter("1"));}}
